 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Detect solid rectangular frames by color.
    frames = []
    for color in {v for row in grid for v in row if v}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1))
                and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1))):
            frames.append((color, r0, r1, c0, c1))

    # Loose dots encode the alternating checker cells. The number of dots of a
    # color equals the number of cells filled in that frame's interior.
    frame_cells = set()
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    frame_cells.add((r, c))
    loose_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                           if grid[r][c] and (r, c) not in frame_cells)

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
        target_count = ((r1 - r0 - 1) * (c1 - c0 - 1) + 1) // 2
        stamp = next((col for col, n in loose_counts.items() if n == target_count), None)
        if stamp is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r - r0 - 1 + c - c0 - 1) % 2 == 0:
                        out[r][c] = stamp
    return out
