 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    # Frames are individual 4-connected components; isolated same-color dots
    # elsewhere in the scene must not enlarge a frame's bounding box.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            cellset = set(cells)
            perimeter = ({(r0, x) for x in range(c0, c1 + 1)} |
                         {(r1, x) for x in range(c0, c1 + 1)} |
                         {(y, c0) for y in range(r0, r1 + 1)} |
                         {(y, c1) for y in range(r0, r1 + 1)})
            if perimeter <= cellset:
                frames.append((color, r0, r1, c0, c1, perimeter))

    frame_border_cells = set()
    for _, _, _, _, _, perimeter in frames:
        frame_border_cells |= perimeter
    loose = Counter(grid[r][c] for r in range(h) for c in range(w)
                    if grid[r][c] and (r, c) not in frame_border_cells)

    out = [[0] * w for _ in range(h)]
    for frame_color, r0, r1, c0, c1, _ in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = frame_color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = frame_color
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        target = (ih * iw + 1) // 2
        stamp = next((color for color, count in loose.items() if count == target), None)
        if stamp is not None:
            for r in range(ih):
                for c in range(iw):
                    if (r + c) % 2 == 0:
                        out[r0 + 1 + r][c0 + 1 + c] = stamp
    return out
